#[inductive(update_place_ops_in_log_one)]
fn update_place_ops_in_log_one_inductive(pre: Self, post: Self, node_id: NodeId, rid: ReqId) {
    let queued_ops = pre.combiner[node_id].get_Placed_queued_ops();
    let op = pre.local_updates[rid].get_Init_op();
    let log_entry = LogEntry { op, node_id };

    // Basic facts about the transition
    assert(post.tail == pre.tail + 1);
    assert(post.log == pre.log.insert(pre.tail, log_entry));
    assert(post.local_updates[rid] == (UpdateState::Placed { op, idx: pre.tail }));
    assert(log_entry.node_id == node_id);
    assert(log_entry.op == op);

    // pre.local_updates[rid] is Init – not Placed, Applied, or Done
    assert(!pre.local_updates[rid].is_Placed());
    assert(!pre.local_updates[rid].is_Applied());
    assert(!pre.local_updates[rid].is_Done());

    // rid is NOT in node_id's current queue (all queued ops are Placed, but rid is Init)
    assert(!queued_ops.contains(rid)) by {
        assert(QueueRidsUpdatePlaced(queued_ops, pre.local_updates, 0));
        assert forall |j: int| 0 <= j < queued_ops.len() implies queued_ops[j] != rid by {
            assert(pre.local_updates.contains_key(queued_ops[j]));
            assert(pre.local_updates[queued_ops[j]].is_Placed());
            if queued_ops[j] == rid {
                assert(pre.local_updates[rid].is_Placed());
                assert(false);
            }
        };
    };

    // For all rid' != rid, post.local_updates agrees with pre.local_updates
    assert(forall |rid2: ReqId| rid2 != rid && pre.local_updates.contains_key(rid2) ==>
        post.local_updates.contains_key(rid2) &&
        post.local_updates[rid2] === pre.local_updates[rid2]);

    // ---- Prove inv_read_results ----
    // The log only changed at pre.tail (>= version_upper_bound), so
    // compute_nrstate_at_version is unchanged for any v <= version_upper_bound.
    assert(post.inv_read_results()) by {
        assert forall |rid0| #[trigger] post.local_reads.contains_key(rid0)
            implies post.read_results_match(post.local_reads[rid0])
        by {
            match post.local_reads[rid0] {
                ReadonlyState::Done { ret, version_upper_bound, op: read_op, .. } => {
                    let ver = choose |v: nat|
                        (#[trigger] rangeincl(version_upper_bound, v, pre.version_upper_bound))
                        && ret == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v), read_op);
                    assert(ver <= pre.version_upper_bound);
                    assert(ver <= pre.tail);
                    compute_nrstate_at_version_preserves(pre.log, post.log, ver);
                    assert(rangeincl(version_upper_bound, ver, post.version_upper_bound));
                    assert(ret == DT::dispatch_spec(
                        compute_nrstate_at_version(post.log, ver), read_op));
                }
                _ => {}
            }
        }
    };

    // ---- Prove combiner_states_wf ----
    assert(post.combiner_states_wf()) by {
        assert forall |node_id0: NodeId| #[trigger] post.combiner.contains_key(node_id0)
            implies post.wf_combiner_for_node_id(node_id0)
        by {
            if node_id0 == node_id {
                // ---- node_id's own combiner: Placed{queued_ops} -> Placed{queued_ops.push(rid)} ----
                assert(pre.wf_combiner_for_node_id(node_id));

                // LogRangeMatchesQueue for the extended queue/log
                LogRangeMatchesQueue_append(
                    queued_ops, pre.log, post.log, 0,
                    pre.local_versions[node_id], pre.tail, node_id,
                    pre.local_updates, post.local_updates, rid, log_entry,
                );
                // => LogRangeMatchesQueue(queued_ops.push(rid), post.log, 0,
                //        local_versions[node_id], tail+1, node_id, post.local_updates)

                // QueueRidsUpdatePlaced for queued_ops.push(rid) from index 0
                assert(QueueRidsUpdatePlaced(queued_ops.push(rid), post.local_updates, 0)) by {
                    assert forall |j: int| 0 <= j < queued_ops.push(rid).len()
                        implies (
                            post.local_updates.contains_key(#[trigger] queued_ops.push(rid)[j])
                            && post.local_updates[queued_ops.push(rid)[j]].is_Placed()
                        )
                    by {
                        if (j as nat) < queued_ops.len() {
                            assert(queued_ops.push(rid)[j] == queued_ops[j]);
                            let r = queued_ops[j];
                            assert(r != rid) by {
                                if r == rid {
                                    assert(queued_ops.contains(rid));
                                    assert(false);
                                }
                            };
                            assert(post.local_updates[r] == pre.local_updates[r]);
                        } else {
                            assert(j as nat == queued_ops.len());
                            assert(queued_ops.push(rid)[j] == rid);
                        }
                    };
                };

                // seq_unique for queued_ops.push(rid)
                assert(seq_unique(queued_ops.push(rid))) by {
                    assert(seq_unique(queued_ops));
                    assert forall |i: int, j: int|
                        0 <= i < queued_ops.push(rid).len() &&
                        0 <= j < queued_ops.push(rid).len() && i != j
                        implies queued_ops.push(rid)[i] !== queued_ops.push(rid)[j]
                    by {
                        if i == queued_ops.len() as int {
                            // queued_ops.push(rid)[i] == rid, and j < len
                            assert(queued_ops.push(rid)[i] == rid);
                            assert((j as nat) < queued_ops.len());
                            let r = queued_ops[j];
                            assert(queued_ops.push(rid)[j] == r);
                            // r is in queued_ops, which doesn't contain rid
                            assert(queued_ops.contains(r));
                            assert(!queued_ops.contains(rid));
                        } else if j == queued_ops.len() as int {
                            assert(queued_ops.push(rid)[j] == rid);
                            assert((i as nat) < queued_ops.len());
                            let r = queued_ops[i];
                            assert(queued_ops.push(rid)[i] == r);
                            assert(queued_ops.contains(r));
                            assert(!queued_ops.contains(rid));
                        } else {
                            // Both indices within the original queued_ops
                            assert(queued_ops.push(rid)[i] == queued_ops[i]);
                            assert(queued_ops.push(rid)[j] == queued_ops[j]);
                        }
                    };
                };

                assert(post.wf_combiner_for_node_id(node_id));

            } else {
                // ---- Other combiners: combiner state unchanged ----
                assert(post.combiner[node_id0] == pre.combiner[node_id0]);
                assert(pre.wf_combiner_for_node_id(node_id0));

                match pre.combiner[node_id0] {
                    CombinerState::Ready => {
                        // LogRangeNoNodeId extends to post.tail (new entry has node_id != node_id0)
                        assert(LogRangeNoNodeId(
                            pre.log, pre.local_versions[node_id0], pre.tail, node_id0));
                        LogRangeNoNodeId_append_other(
                            pre.log, post.log,
                            pre.local_versions[node_id0], pre.tail, node_id0, log_entry,
                        );
                    }
                    CombinerState::Placed { queued_ops: qops0 } => {
                        // rid is not in qops0 (same reasoning: all entries must be Placed)
                        assert(!qops0.contains(rid)) by {
                            assert(QueueRidsUpdatePlaced(qops0, pre.local_updates, 0));
                            assert forall |j: int| 0 <= j < qops0.len() implies qops0[j] != rid by {
                                assert(pre.local_updates.contains_key(qops0[j]));
                                assert(pre.local_updates[qops0[j]].is_Placed());
                                if qops0[j] == rid {
                                    assert(pre.local_updates[rid].is_Placed());
                                    assert(false);
                                }
                            };
                        };
                        // Extend LogRangeMatchesQueue to cover new tail
                        LogRangeMatchesQueue_append_other_augment(
                            qops0, pre.log, post.log, 0,
                            pre.local_versions[node_id0], pre.tail, node_id0,
                            pre.local_updates, post.local_updates, rid, log_entry,
                        );
                        // QueueRidsUpdatePlaced preserved (rid not in qops0)
                        assert(QueueRidsUpdatePlaced(qops0, post.local_updates, 0)) by {
                            assert forall |j: int| 0 <= j < qops0.len() implies
                                post.local_updates.contains_key(#[trigger] qops0[j])
                                && post.local_updates[qops0[j]].is_Placed()
                            by {
                                let r = qops0[j];
                                assert(r != rid) by {
                                    if r == rid { assert(qops0.contains(rid)); assert(false); }
                                };
                                assert(post.local_updates[r] == pre.local_updates[r]);
                            };
                        };
                    }
                    CombinerState::LoadedLocalVersion { queued_ops: qops0, lversion } => {
                        assert(!qops0.contains(rid)) by {
                            assert(QueueRidsUpdatePlaced(qops0, pre.local_updates, 0));
                            assert forall |j: int| 0 <= j < qops0.len() implies qops0[j] != rid by {
                                assert(pre.local_updates.contains_key(qops0[j]));
                                assert(pre.local_updates[qops0[j]].is_Placed());
                                if qops0[j] == rid {
                                    assert(pre.local_updates[rid].is_Placed());
                                    assert(false);
                                }
                            };
                        };
                        LogRangeMatchesQueue_append_other_augment(
                            qops0, pre.log, post.log, 0,
                            lversion, pre.tail, node_id0,
                            pre.local_updates, post.local_updates, rid, log_entry,
                        );
                        assert(QueueRidsUpdatePlaced(qops0, post.local_updates, 0)) by {
                            assert forall |j: int| 0 <= j < qops0.len() implies
                                post.local_updates.contains_key(#[trigger] qops0[j])
                                && post.local_updates[qops0[j]].is_Placed()
                            by {
                                let r = qops0[j];
                                assert(r != rid) by {
                                    if r == rid { assert(qops0.contains(rid)); assert(false); }
                                };
                                assert(post.local_updates[r] == pre.local_updates[r]);
                            };
                        };
                    }
                    CombinerState::Loop { queued_ops: qops0, idx, lversion, tail: tail0 } => {
                        // rid is not in qops0
                        assert(!qops0.contains(rid)) by {
                            assert forall |j: int| 0 <= j < qops0.len() implies qops0[j] != rid by {
                                if (j as nat) < idx {
                                    // QueueRidsUpdateDone: applied or done, not init
                                    assert(QueueRidsUpdateDone(qops0, pre.local_updates, idx));
                                    if qops0[j] == rid {
                                        assert(pre.local_updates.contains_key(qops0[j]));
                                        assert(pre.local_updates[qops0[j]].is_Applied()
                                            || pre.local_updates[qops0[j]].is_Done());
                                        assert(pre.local_updates[rid].is_Applied()
                                            || pre.local_updates[rid].is_Done());
                                        assert(false);
                                    }
                                } else {
                                    // QueueRidsUpdatePlaced: placed, not init
                                    assert(QueueRidsUpdatePlaced(qops0, pre.local_updates, idx));
                                    assert(pre.local_updates.contains_key(qops0[j]));
                                    assert(pre.local_updates[qops0[j]].is_Placed());
                                    if qops0[j] == rid {
                                        assert(pre.local_updates[rid].is_Placed());
                                        assert(false);
                                    }
                                }
                            };
                        };
                        // Extend LogRangeMatchesQueue (range [lversion, tail0), log change at pre.tail >= tail0)
                        LogRangeMatchesQueue_append_other(
                            qops0, pre.log, post.log, idx, lversion, tail0, pre.tail,
                            node_id0, pre.local_updates, post.local_updates, rid, log_entry,
                        );
                        // Extend LogRangeNoNodeId from [tail0, pre.tail) to [tail0, pre.tail+1)
                        LogRangeNoNodeId_append_other(
                            pre.log, post.log, tail0, pre.tail, node_id0, log_entry,
                        );
                        // QueueRidsUpdatePlaced preserved
                        assert(QueueRidsUpdatePlaced(qops0, post.local_updates, idx)) by {
                            assert forall |j: int| (idx as int) <= j < qops0.len() implies
                                post.local_updates.contains_key(#[trigger] qops0[j])
                                && post.local_updates[qops0[j]].is_Placed()
                            by {
                                let r = qops0[j];
                                assert(r != rid) by {
                                    if r == rid { assert(qops0.contains(rid)); assert(false); }
                                };
                                assert(post.local_updates[r] == pre.local_updates[r]);
                            };
                        };
                        // QueueRidsUpdateDone preserved
                        assert(QueueRidsUpdateDone(qops0, post.local_updates, idx)) by {
                            assert forall |j: int| 0 <= j < (idx as int) implies
                                post.local_updates.contains_key(#[trigger] qops0[j]) ==>
                                (post.local_updates[qops0[j]].is_Applied()
                                    || post.local_updates[qops0[j]].is_Done())
                            by {
                                let r = qops0[j];
                                assert(r != rid) by {
                                    if r == rid { assert(qops0.contains(rid)); assert(false); }
                                };
                                assert(post.local_updates.contains_key(r) ==>
                                    post.local_updates[r] == pre.local_updates[r]);
                            };
                        };
                    }
                    CombinerState::UpdatedVersion { queued_ops: qops0, tail: tail0 } => {
                        // rid is not in qops0
                        assert(!qops0.contains(rid)) by {
                            assert(QueueRidsUpdateDone(qops0, pre.local_updates, qops0.len()));
                            assert forall |j: int| 0 <= j < qops0.len() implies qops0[j] != rid by {
                                if qops0[j] == rid {
                                    assert(pre.local_updates.contains_key(qops0[j]));
                                    assert(pre.local_updates[qops0[j]].is_Applied()
                                        || pre.local_updates[qops0[j]].is_Done());
                                    assert(pre.local_updates[rid].is_Applied()
                                        || pre.local_updates[rid].is_Done());
                                    assert(false);
                                }
                            };
                        };
                        // Extend LogRangeNoNodeId
                        LogRangeNoNodeId_append_other(
                            pre.log, post.log, tail0, pre.tail, node_id0, log_entry,
                        );
                        // QueueRidsUpdateDone preserved
                        assert(QueueRidsUpdateDone(qops0, post.local_updates, qops0.len())) by {
                            assert forall |j: int| 0 <= j < qops0.len() implies
                                post.local_updates.contains_key(#[trigger] qops0[j]) ==>
                                (post.local_updates[qops0[j]].is_Applied()
                                    || post.local_updates[qops0[j]].is_Done())
                            by {
                                let r = qops0[j];
                                assert(r != rid) by {
                                    if r == rid { assert(qops0.contains(rid)); assert(false); }
                                };
                                assert(post.local_updates.contains_key(r) ==>
                                    post.local_updates[r] == pre.local_updates[r]);
                            };
                        };
                    }
                }
            }
        }
    };
