                    assert(pre.local_updates[rid0].is_Done());
                    assert(idx < pre.version_upper_bound);
                    assert(idx < pre.tail);
                    assert(post.log[idx] == pre.log[idx]);
                    compute_nrstate_at_version_preserves(pre.log, post.log, idx);
                }
                _ => {}
            }
        }
